def test_consume_prefix_in_state_dict_if_present():
    solution = Solution()

    # Test case where no keys have the prefix
    state_dict_no_prefix = {
        "key1": [1, 2, 3],
        "key2": {"a": 1}
    }
    prefix = "prefix."
    solution.consume_prefix_in_state_dict_if_present(state_dict_no_prefix, prefix)

    assert state_dict_no_prefix == {
        "key1": [1, 2, 3],
        "key2": {"a": 1}
    }

    # Test case where some keys have the prefix
    state_dict_with_prefix = OrderedDict([
        ("prefix.key1", [1, 2, 3]),
        ("prefix.key2", {"a": 1}),
        ("other.key", [4, 5])
    ])
    solution.consume_prefix_in_state_dict_if_present(state_dict_with_prefix, prefix)
    assert state_dict_with_prefix == OrderedDict([
        ("key1", [1, 2, 3]),
        ("key2", {"a": 1}),
        ("other.key", [4, 5])
    ])

    # Test case where all keys have the prefix
    state_dict_all_prefix = OrderedDict([
        ("prefix.key1", [1, 2, 3]),
        ("prefix.key2", {"a": 1})
    ])
    solution.consume_prefix_in_state_dict_if_present(state_dict_all_prefix, prefix)
    assert state_dict_all_prefix == OrderedDict([
        ("key1", [1, 2, 3]),
        ("key2", {"a": 1})
    ])

